        JsonNode current=json(mvc.perform(post("/api/v1/processes/P012/promotion-requests").header("Authorization",bearer(manager)).header("Idempotency-Key","create-nomination").contentType(MediaType.APPLICATION_JSON).content(create.toString())).andExpect(status().isOk()).andReturn());String requestId=current.path("id").asText();assertEquals("S01",current.path("currentNodeCode").asText());assertEquals(requestId,json(mvc.perform(post("/api/v1/processes/P012/promotion-requests").header("Authorization",bearer(manager)).header("Idempotency-Key","create-nomination").contentType(MediaType.APPLICATION_JSON).content(create.toString())).andExpect(status().isOk()).andReturn()).path("id").asText());
        assertEquals(0,json(mvc.perform(get("/api/v1/processes/P012/promotion-requests").header("Authorization",bearer(outsider))).andExpect(status().isOk()).andReturn()).size());mvc.perform(get("/api/v1/processes/P012/promotion-requests/"+requestId).header("Authorization",bearer(outsider))).andExpect(status().isForbidden());JsonNode masked=json(mvc.perform(get("/api/v1/processes/P012/promotion-requests/"+requestId).header("Authorization",bearer(tech))).andExpect(status().isOk()).andReturn());assertTrue(masked.path("reason").isNull());assertTrue(masked.path("personName").isNull());assertTrue(masked.path("personNo").isNull());assertTrue(masked.path("score1000").isNull());assertTrue(masked.path("events").isArray()&&masked.path("events").isEmpty());assertTrue(masked.path("executions").isArray()&&masked.path("executions").isEmpty());
        mvc.perform(post(actionUrl(requestId,"SUBMIT")).header("Authorization",bearer(manager)).header("Idempotency-Key","stale").contentType(MediaType.APPLICATION_JSON).content(action(0).toString())).andExpect(status().isConflict());current=act(manager,requestId,"SUBMIT",1,action(1),"submit-nomination");mvc.perform(post(actionUrl(requestId,"CHECK_ELIGIBILITY")).header("Authorization",bearer(manager)).header("Idempotency-Key","frozen").contentType(MediaType.APPLICATION_JSON).content(action(2).put("eligibilityConfirmed",true).put("freezeClear",false).toString())).andExpect(status().isConflict());current=act(manager,requestId,"CHECK_ELIGIBILITY",2,action(2).put("eligibilityConfirmed",true).put("freezeClear",true),"eligibility");mvc.perform(post(actionUrl(requestId,"RECORD_ASSESSMENT")).header("Authorization",bearer(assessor)).header("Idempotency-Key","score-overflow").contentType(MediaType.APPLICATION_JSON).content(action(3).put("score1000",1001).toString())).andExpect(status().isConflict());current=act(assessor,requestId,"RECORD_ASSESSMENT",3,action(3).put("score1000",912),"assessment");current=act(manager,requestId,"VERIFY_VACANCY_BUDGET",4,action(4).put("vacancyConfirmed",true).put("budgetVerificationReference","BUDGET-AUTH-2026-012"),"vacancy-budget");mvc.perform(post(actionUrl(requestId,"COMPLETE_REVIEW")).header("Authorization",bearer(assessor)).header("Idempotency-Key","self-review").contentType(MediaType.APPLICATION_JSON).content(action(5).put("reviewPassed",true).toString())).andExpect(status().isConflict());current=act(reviewer,requestId,"COMPLETE_REVIEW",5,action(5).put("reviewPassed",true),"review");mvc.perform(post(actionUrl(requestId,"APPROVE")).header("Authorization",bearer(reviewer)).header("Idempotency-Key","reviewer-approve").contentType(MediaType.APPLICATION_JSON).content(action(6).put("approved",true).toString())).andExpect(status().isForbidden());current=act(approver,requestId,"APPROVE",6,action(6).put("approved",true),"approve");
        JdbcTemplate oms=jdbc("sjg_oms",POSTGRES.getUsername(),POSTGRES.getPassword());assertEquals(OLD_APPOINTMENT,oms.queryForObject("select id from org.employee_position where tenant_id=? and employee_id=? and is_primary and status='ACTIVE'",UUID.class,TENANT,OWNER));assertEquals(OLD_POSITION,oms.queryForObject("select primary_position_id from org.employee where tenant_id=? and id=?",UUID.class,TENANT,OWNER));assertEquals(0,oms.queryForObject("select count(*) from hr.promotion_appointment_execution where tenant_id=? and request_id=?",Integer.class,TENANT,UUID.fromString(requestId)));
        current=act(manager,requestId,"COMPLETE_NOTICE",7,action(7),"notice");mvc.perform(post(actionUrl(requestId,"RECORD_APPOINTMENT")).header("Authorization",bearer(appointer)).header("Idempotency-Key","missing-salary-authority").contentType(MediaType.APPLICATION_JSON).content(action(8).put("actualEffectiveDate",LocalDate.now().plusDays(30).toString()).put("externalReference","APPOINTMENT-2026-012").toString())).andExpect(status().isConflict());current=act(appointer,requestId,"RECORD_APPOINTMENT",8,action(8).put("actualEffectiveDate",LocalDate.now().plusDays(30).toString()).put("salaryConfirmationReference","SALARY-AUTHORITY-2026-012").put("externalReference","APPOINTMENT-2026-012"),"appointment-receipt");mvc.perform(post(actionUrl(requestId,"CONFIRM_APPOINTMENT")).header("Authorization",bearer(appointer)).header("Idempotency-Key","not-owner-confirm").contentType(MediaType.APPLICATION_JSON).content(action(9).toString())).andExpect(status().isConflict());current=act(owner,requestId,"CONFIRM_APPOINTMENT",9,action(9),"owner-confirm");current=act(reviewer,requestId,"COMPLETE_PROBATION",10,action(10).put("probationResult","PASS"),"probation-pass");LocalDate effective=LocalDate.now().plusDays(30);current=act(appointer,requestId,"MAKE_EFFECTIVE",11,action(11).put("actualEffectiveDate",effective.toString()).put("externalReference","EFFECTIVE-2026-012"),"effective");assertEquals("END",current.path("currentNodeCode").asText());UUID newAppointment=oms.queryForObject("select id from org.employee_position where tenant_id=? and employee_id=? and is_primary and status='ACTIVE'",UUID.class,TENANT,OWNER);assertTrue(!OLD_APPOINTMENT.equals(newAppointment));assertEquals(NEW_POSITION,oms.queryForObject("select position_id from org.employee_position where id=?",UUID.class,newAppointment));assertEquals(NEW_POSITION,oms.queryForObject("select primary_position_id from org.employee where tenant_id=? and id=?",UUID.class,TENANT,OWNER));assertEquals(effective.minusDays(1),oms.queryForObject("select effective_end_date from org.employee_position where id=?",LocalDate.class,OLD_APPOINTMENT));assertEquals(1,oms.queryForObject("select count(*) from hr.promotion_appointment_execution where tenant_id=? and request_id=? and execution_type='EFFECTIVE'",Integer.class,TENANT,UUID.fromString(requestId)));assertTrue(jdbc("sjg_audit",POSTGRES.getUsername(),POSTGRES.getPassword()).queryForObject("select count(*) from audit.operation_log where tenant_id=? and resource_id=? and action like 'P012_%'",Integer.class,TENANT,UUID.fromString(requestId))>=15);
